import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] l = new long[n], rr = new long[n];
        for (int i = 0; i < n; i++) { l[i] = r.nextLong(); rr[i] = r.nextLong(); }
        long[] starts = l.clone(), ends = rr.clone();
        Arrays.sort(starts);
        Arrays.sort(ends);
        long best = 0;
        for (int i = 0; i < n; i++) {
            // starts <= rr[i] minus ends < l[i]
            int lo = 0, hi = n;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (starts[mid] <= rr[i]) lo = mid + 1; else hi = mid; }
            int a = lo;
            lo = 0; hi = n;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (ends[mid] < l[i]) lo = mid + 1; else hi = mid; }
            best = Math.max(best, a - lo);
        }
        System.out.println(n - best);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

