func main() {
	n := readInt()
	l := make([]int, n)
	r := make([]int, n)
	for i := 0; i < n; i++ {
		l[i], r[i] = readInt(), readInt()
	}
	starts, ends := slices.Clone(l), slices.Clone(r)
	slices.Sort(starts)
	slices.Sort(ends)
	best := 0
	for i := 0; i < n; i++ {
		// starts <= r[i] minus ends < l[i]
		keep := sort.SearchInts(starts, r[i]+1) - sort.SearchInts(ends, l[i])
		best = max(best, keep)
	}
	fmt.Println(n - best)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
